package pfm.android;

import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;

/** Structured top-five competition center built on the v42 deterministic world engine. */
public final class NativeWorldCompetition{
 private NativeWorldCompetition(){} static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);} static TextView text(Context c,String s,float z,boolean b){TextView v=new TextView(c);v.setText(s);v.setTextSize(z);v.setPadding(dp(c,6),dp(c,5),dp(c,6),dp(c,5));if(b)v.setTypeface(android.graphics.Typeface.DEFAULT,1);return v;}
 static int year(){int s=NativeWorldCenter.season();return s>=2000?s:2010+s;} static int rounds(String c){return "de".equals(c)?34:38;} static String pos(int p){return p==0?"GK":p==1?"DEF":p==2?"MID":"FW";}
 static View badge(Context c,String code,int id){ImageView v=new ImageView(c);try{InputStream in=c.getAssets().open("badges/"+code+(id+1)+".png");v.setImageBitmap(android.graphics.BitmapFactory.decodeStream(in));in.close();}catch(Throwable ignored){}v.setScaleType(ImageView.ScaleType.FIT_CENTER);return v;}
 static int zone(String c,int r,int n){int cl=("en".equals(c)||"es".equals(c)||"it".equals(c))?4:3,el="fr".equals(c)?1:2,rel="de".equals(c)?2:3;if(r<=cl)return 0xffdcecff;if(r<=cl+el)return 0xffffefc2;if(r>n-rel)return 0xffffdddd;return Color.TRANSPARENT;}
 static ArrayList<NativeWorldCenter.T> ordered(ArrayList<NativeWorldCenter.T> ts){ArrayList<NativeWorldCenter.T> x=new ArrayList<NativeWorldCenter.T>(ts);Collections.sort(x,(a,b)->b.pts!=a.pts?b.pts-a.pts:(b.gf-b.ga)!=(a.gf-a.ga)?(b.gf-b.ga)-(a.gf-a.ga):b.gf-a.gf);return x;}
 static TextView cell(Context c,String s,float w,boolean b){TextView v=text(c,s,9.8f,b);v.setGravity(Gravity.CENTER);v.setSingleLine(true);v.setLayoutParams(new LinearLayout.LayoutParams(0,dp(c,26),w));return v;}
 static View tableRow(Context c,String code,NativeWorldCenter.T t,int rank,boolean head){LinearLayout r=new LinearLayout(c);r.setGravity(Gravity.CENTER_VERTICAL);if(!head){r.addView(badge(c,code,t.id),new LinearLayout.LayoutParams(dp(c,24),dp(c,24)));GradientDrawable g=new GradientDrawable();g.setColor(zone(code,rank,NativeWorldCenter.leagues.get(code).size()));r.setBackground(g);}else r.addView(new Space(c),new LinearLayout.LayoutParams(dp(c,24),1));String[] a=head?new String[]{"#","CLUB","P","W","D","L","GF","GA","GD","PTS"}:new String[]{String.valueOf(rank),t.name,String.valueOf(t.p),String.valueOf(t.w),String.valueOf(t.d),String.valueOf(t.l),String.valueOf(t.gf),String.valueOf(t.ga),String.valueOf(t.gf-t.ga),String.valueOf(t.pts)};float[] w={.5f,3.2f,.55f,.55f,.55f,.55f,.65f,.65f,.7f,.8f};for(int i=0;i<a.length;i++){TextView v=cell(c,a[i],w[i],head||i==1||i==9);if(i==1)v.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);r.addView(v);}return r;}
 static ArrayAdapter<String> stringAdapter(Activity a,ArrayList<String> rows){return new ArrayAdapter<String>(a,android.R.layout.simple_list_item_1,rows){public View getView(int n,View v,ViewGroup p){return text(a,getItem(n),13f,n<3);}};}
 static void profile(Activity a,NativeWorldCenter.P p,String club){String rat=p.ap==0?"n/a":String.format(Locale.US,"%.1f",p.rs/(10.0*p.ap));String body="Club: "+club+"\nNationality: "+p.nat.split(" • ")[0]+"\nPosition: "+pos(p.pos)+"\nAge: "+p.age+"\nOverall: "+p.ovr+"\n\nSeason statistics\nAppearances: "+p.ap+"\nGoals: "+p.g+"\nAssists: "+p.a+"\nAverage rating: "+rat;if(p.pos==0)body+="\nClean sheets: "+p.cs+"\nConceded: "+p.ga+"\nSaves: "+p.sv;new AlertDialog.Builder(a).setTitle(p.name).setMessage(body).setPositiveButton("Close",null).show();}
 static void club(Activity a,String code,NativeWorldCenter.T t){ArrayList<NativeWorldCenter.P> ps=new ArrayList<NativeWorldCenter.P>(t.ps);Collections.sort(ps,(x,y)->x.pos!=y.pos?x.pos-y.pos:y.ovr-x.ovr);ListView l=new ListView(a);l.setAdapter(new ArrayAdapter<NativeWorldCenter.P>(a,android.R.layout.simple_list_item_1,ps){public View getView(int n,View v,ViewGroup g){NativeWorldCenter.P p=getItem(n);LinearLayout r=new LinearLayout(a);r.setOrientation(LinearLayout.VERTICAL);r.addView(text(a,p.name+"  ·  "+p.nat.split(" • ")[0],14f,true));r.addView(text(a,pos(p.pos)+"   AGE "+p.age+"   OVR "+p.ovr+"   G "+p.g+" A "+p.a,11.5f,false));return r;}});l.setOnItemClickListener((x,v,n,id)->profile(a,ps.get(n),t.name));AlertDialog d=new AlertDialog.Builder(a).setTitle(t.name+" — "+t.ps.size()+" players").setView(l).setPositiveButton("Close",null).create();d.setOnShowListener(v->{Window w=d.getWindow();if(w!=null)w.setLayout(-1,Math.round(a.getResources().getDisplayMetrics().heightPixels*.9f));});d.show();}
 public static void show(Activity a){NativeWorldCenter.load(a);if(NativeWorldCenter.leagues.isEmpty()){Toast.makeText(a,"World data unavailable",0).show();return;}boolean paused=NativePause.begin();LinearLayout root=new LinearLayout(a);root.setOrientation(LinearLayout.VERTICAL);Spinner league=new Spinner(a);league.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,NativeWorldCenter.N));root.addView(league);HorizontalScrollView hs=new HorizontalScrollView(a);LinearLayout nav=new LinearLayout(a);String[] labels={"TABLE","CALENDAR","STATISTICS","CLUBS","HISTORY"};Button[] bs=new Button[5];for(int i=0;i<5;i++){bs[i]=new Button(a);bs[i].setText(labels[i]);nav.addView(bs[i]);}hs.addView(nav);root.addView(hs);Spinner sub=new Spinner(a);root.addView(sub);LinearLayout head=new LinearLayout(a);root.addView(head);ListView list=new ListView(a);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));final int[] mode={0};final Runnable[] refresh=new Runnable[1];refresh[0]=()->{String code=NativeWorldCenter.C[league.getSelectedItemPosition()];int through=NativeWorldCenter.progress(code);ArrayList<NativeWorldCenter.T> ts=NativeWorldCenter.leagues.get(code);ArrayList<NativeWorldCenter.M> ms;head.removeAllViews();sub.setVisibility((mode[0]==1||mode[0]==2||mode[0]==4)?View.VISIBLE:View.GONE);if(mode[0]==4){int selected=sub.getSelectedItemPosition();int sy=2010+selected;NativeWorldCenter.simulateAt(code,rounds(code),sy);ArrayList<NativeWorldCenter.T> order=ordered(ts);head.addView(tableRow(a,code,null,0,true));ArrayList<View> rows=new ArrayList<View>();int r=1;for(NativeWorldCenter.T t:order)rows.add(tableRow(a,code,t,r++,false));list.setAdapter(new ArrayAdapter<View>(a,0,rows){public View getView(int n,View v,ViewGroup p){return getItem(n);}});return;}ms=NativeWorldCenter.simulate(code,through);if(mode[0]==0){head.addView(tableRow(a,code,null,0,true));ArrayList<View> rows=new ArrayList<View>();int r=1;for(NativeWorldCenter.T t:ordered(ts))rows.add(tableRow(a,code,t,r++,false));list.setAdapter(new ArrayAdapter<View>(a,0,rows){public View getView(int n,View v,ViewGroup p){return getItem(n);}});}else if(mode[0]==1){int round=sub.getSelectedItemPosition()+1;ArrayList<String> rows=new ArrayList<String>();for(NativeWorldCenter.M m:ms)if(m.r==round){boolean done=round<=through;rows.add(ts.get(m.h).name+"   "+(done?m.hg+" – "+m.ag:"vs")+"   "+ts.get(m.a).name);}list.setAdapter(stringAdapter(a,rows));}else if(mode[0]==2){int metric=sub.getSelectedItemPosition();ArrayList<NativeWorldCenter.P> ps=new ArrayList<NativeWorldCenter.P>();for(NativeWorldCenter.T t:ts)ps.addAll(t.ps);Collections.sort(ps,(x,y)->value(y,metric)-value(x,metric));ArrayList<String> rows=new ArrayList<String>();for(int i=0;i<Math.min(100,ps.size());i++){NativeWorldCenter.P p=ps.get(i);String rat=p.ap==0?"n/a":String.format(Locale.US,"%.1f",p.rs/(10.0*p.ap));rows.add((i+1)+". "+p.name+"  ·  "+p.nat.split(" • ")[0]+"\nG "+p.g+"  A "+p.a+"  AP "+p.ap+"  RAT "+rat+(p.pos==0?"  CS "+p.cs+" SV "+p.sv:""));}list.setAdapter(stringAdapter(a,rows));}else{ArrayList<NativeWorldCenter.T> clubs=new ArrayList<NativeWorldCenter.T>(ts);Collections.sort(clubs,(x,y)->x.name.compareToIgnoreCase(y.name));ArrayList<String> rows=new ArrayList<String>();for(NativeWorldCenter.T t:clubs)rows.add(t.name+"\n"+t.ps.size()+" players   OVR "+t.ovr);list.setAdapter(stringAdapter(a,rows));list.setOnItemClickListener((p,v,n,id)->club(a,code,clubs.get(n)));}};
  league.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){configureSub(a,sub,mode[0],NativeWorldCenter.C[n]);refresh[0].run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});sub.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){refresh[0].run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});for(int i=0;i<5;i++){final int m=i;bs[i].setOnClickListener(v->{mode[0]=m;list.setOnItemClickListener(null);configureSub(a,sub,m,NativeWorldCenter.C[league.getSelectedItemPosition()]);refresh[0].run();});}configureSub(a,sub,0,"en");refresh[0].run();AlertDialog d=new AlertDialog.Builder(a).setTitle("World Competition Center").setView(root).setPositiveButton("Close",null).create();d.setOnDismissListener(v->NativePause.end(paused));d.setOnShowListener(v->{Window w=d.getWindow();if(w!=null)w.setLayout(-1,Math.round(a.getResources().getDisplayMetrics().heightPixels*.95f));});d.show();}
 static int value(NativeWorldCenter.P p,int m){return m==0?p.g:m==1?p.a:m==2?(p.ap==0?0:p.rs/p.ap):m==3?p.ap:p.cs;}
 static void configureSub(Context c,Spinner s,int mode,String code){ArrayList<String> x=new ArrayList<String>();if(mode==1)for(int i=1;i<=rounds(code);i++)x.add("MATCHDAY "+i);else if(mode==2)Collections.addAll(x,"GOALS","ASSISTS","RATING","APPEARANCES","GK CLEAN SHEETS");else if(mode==4){int end=Math.max(2010,year()-1);for(int y=2010;y<=end;y++)x.add(y+"/"+(y+1));}s.setAdapter(new ArrayAdapter<String>(c,android.R.layout.simple_spinner_dropdown_item,x));}
}
